import{_ as o,o as t,c as a,a2 as r}from"./chunks/framework.BXzK3EA4.js";const p=JSON.parse('{"title":"Tool References","description":"","frontmatter":{},"headers":[],"relativePath":"mcp/tool-references.md","filePath":"mcp/tool-references.md"}'),d={name:"mcp/tool-references.md"};function i(l,e,s,n,c,u){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="tool-references" tabindex="-1">Tool References <a class="header-anchor" href="#tool-references" aria-label="Permalink to &quot;Tool References&quot;">​</a></h1><h2 id="tradeboard-mcp-tool-reference-prompt-examples" tabindex="-1">Tradeboard MCP: Tool Reference &amp; Prompt Examples <a class="header-anchor" href="#tradeboard-mcp-tool-reference-prompt-examples" aria-label="Permalink to &quot;Tradeboard MCP: Tool Reference &amp; Prompt Examples&quot;">​</a></h2><p>Companion reference to the main MCP setup guide. Once the MCP server is wired into Claude Desktop, Cursor, Windsurf, Antigravity, or any other MCP-capable client, you can ask for these operations in plain English; the client decides which tool to call.</p><p>The supported tools are grouped below. The live MCP <code>tools/list</code> response is authoritative for the exact registry and schemas exposed by a running version. Each entry includes:</p><ul><li>What the tool does</li><li>Key parameters (required / optional)</li><li>Example prompts you can paste directly into Claude / Cursor / Antigravity / Windsurf</li></ul><h3 id="conventions" tabindex="-1">Conventions <a class="header-anchor" href="#conventions" aria-label="Permalink to &quot;Conventions&quot;">​</a></h3><ul><li><strong>Default strategy tag</strong>: <code>python mcp</code>. Every MCP-triggered order is tagged so you can filter MCP activity in Tradeboard logs and the Analyzer. Override by saying <em>&quot;use strategy &#39;my scalper&#39;&quot;</em> in the prompt.</li><li><strong>Product type defaults</strong>: <code>MIS</code> for equity. Use <code>NRML</code> for F&amp;O carry; <code>CNC</code> for delivery.</li><li><strong>Exchange codes</strong>: <code>NSE</code>, <code>BSE</code>, <code>NFO</code>, <code>BFO</code>, <code>CDS</code>, <code>BCD</code>, <code>MCX</code>, <code>NCDEX</code> + <code>NSE_INDEX</code> / <code>BSE_INDEX</code> for index values.</li><li><strong>Toolsets</strong>: every tool belongs to exactly one of <code>orders</code>, <code>account</code>, <code>marketdata</code>, <code>research</code>, or <code>utility</code>. Those five names are the only values <code>TRADEBOARD_MCP_TOOLSETS</code> accepts. The section headings below group tools by task, which does not always match the toolset: <code>close_all_positions</code> and <code>analyzer_toggle</code> are in <code>orders</code>, <code>calculate_margin</code> and <code>analyzer_status</code> are in <code>account</code>, and the calendar and instrument tools are in <code>marketdata</code>.</li><li><strong>Lot size</strong>: never hardcoded. The model will call <code>get_option_symbol</code> / <code>get_option_chain</code> / <code>get_symbol_info</code> to read the live <code>lotsize</code> from the broker master contract, then compute <code>quantity = lots × lotsize</code> for you.</li></ul><hr><h3 id="order-management" tabindex="-1">Order Management <a class="header-anchor" href="#order-management" aria-label="Permalink to &quot;Order Management&quot;">​</a></h3><h4 id="place-order" tabindex="-1"><code>place_order</code> <a class="header-anchor" href="#place-order" aria-label="Permalink to &quot;`place_order`&quot;">​</a></h4><p>Place a single market / limit / stop-loss order.</p><table tabindex="0"><thead><tr><th>Param</th><th>Required</th><th>Notes</th></tr></thead><tbody><tr><td><code>symbol</code>, <code>quantity</code>, <code>action</code></td><td>Yes</td><td>none</td></tr><tr><td><code>exchange</code></td><td>No</td><td>Default <code>NSE</code></td></tr><tr><td><code>price_type</code></td><td>No</td><td><code>MARKET</code>, <code>LIMIT</code>, <code>SL</code>, <code>SL-M</code>. Default <code>MARKET</code></td></tr><tr><td><code>product</code></td><td>No</td><td><code>CNC</code>, <code>NRML</code>, <code>MIS</code>. Default <code>MIS</code></td></tr><tr><td><code>strategy</code></td><td>No</td><td>Default <code>python mcp</code></td></tr><tr><td><code>price</code>, <code>trigger_price</code>, <code>disclosed_quantity</code></td><td>No</td><td>Use as applicable</td></tr></tbody></table><p><strong>Prompts:</strong></p><ul><li><em>&quot;Place a market buy for 100 shares of RELIANCE on NSE, intraday&quot;</em></li><li><em>&quot;Buy 50 INFY at limit 1550, delivery product&quot;</em></li><li><em>&quot;Sell 25 SBIN with a stop-loss at 765 and trigger 766&quot;</em></li></ul><hr><h4 id="place-smart-order" tabindex="-1"><code>place_smart_order</code> <a class="header-anchor" href="#place-smart-order" aria-label="Permalink to &quot;`place_smart_order`&quot;">​</a></h4><p>Auto-calculates the delta between your current position and the target <code>position_size</code>, then sends only the incremental order.</p><table tabindex="0"><thead><tr><th>Param</th><th>Required</th><th>Notes</th></tr></thead><tbody><tr><td><code>symbol</code>, <code>quantity</code>, <code>action</code>, <code>position_size</code></td><td>Yes</td><td><code>position_size</code> = your target net qty</td></tr><tr><td>Rest</td><td>No</td><td>Same defaults as <code>place_order</code></td></tr></tbody></table><p><strong>Prompts:</strong></p><ul><li><em>&quot;Square off my TATAMOTORS intraday position to zero&quot;</em></li><li><em>&quot;Scale my YESBANK position to 100 shares long&quot;</em></li></ul><hr><h4 id="place-basket-order" tabindex="-1"><code>place_basket_order</code> <a class="header-anchor" href="#place-basket-order" aria-label="Permalink to &quot;`place_basket_order`&quot;">​</a></h4><p>Fire multiple orders in one call. Each basket entry carries its own <code>symbol</code>, <code>exchange</code>, <code>action</code>, <code>quantity</code>, <code>pricetype</code>, <code>product</code>.</p><p><strong>Prompts:</strong></p><ul><li><em>&quot;Place a basket: buy 1 BHEL and sell 1 ZOMATO, both market MIS on NSE&quot;</em></li><li><em>&quot;Build a basket of SBIN, HDFCBANK and ICICIBANK buys, 10 shares each, CNC&quot;</em></li></ul><hr><h4 id="place-split-order" tabindex="-1"><code>place_split_order</code> <a class="header-anchor" href="#place-split-order" aria-label="Permalink to &quot;`place_split_order`&quot;">​</a></h4><p>Break a large order into equal chunks (helpful for low-liquidity names or to avoid freeze limits).</p><table tabindex="0"><thead><tr><th>Param</th><th>Required</th><th>Notes</th></tr></thead><tbody><tr><td><code>symbol</code>, <code>exchange</code>, <code>action</code>, <code>quantity</code>, <code>split_size</code></td><td>Yes</td><td><code>split_size</code> is the size of each slice</td></tr><tr><td><code>price_type</code>, <code>product</code>, <code>price</code>, <code>trigger_price</code>, <code>strategy</code></td><td>No</td><td>Same as <code>place_order</code></td></tr></tbody></table><p><strong>Prompts:</strong></p><ul><li><em>&quot;Sell 500 YESBANK in slices of 50, market orders&quot;</em></li><li><em>&quot;Split 1200 NIFTY lots across 100-lot chunks&quot;</em></li></ul><hr><h4 id="place-options-order" tabindex="-1"><code>place_options_order</code> <a class="header-anchor" href="#place-options-order" aria-label="Permalink to &quot;`place_options_order`&quot;">​</a></h4><p>Single-leg option order using offset-based strike selection (ATM / ITM1-ITM50 / OTM1-OTM50). The server resolves the strike against the live option chain.</p><table tabindex="0"><thead><tr><th>Param</th><th>Required</th><th>Notes</th></tr></thead><tbody><tr><td><code>underlying</code>, <code>exchange</code>, <code>offset</code>, <code>option_type</code>, <code>action</code>, <code>quantity</code></td><td>Yes</td><td>none</td></tr><tr><td><code>expiry_date</code></td><td>No</td><td>Optional if underlying includes expiry (e.g., <code>NIFTY28OCT25FUT</code>)</td></tr><tr><td><code>price_type</code>, <code>product</code>, <code>price</code>, <code>trigger_price</code>, <code>disclosed_quantity</code>, <code>strategy</code></td><td>No</td><td>Same as <code>place_order</code></td></tr></tbody></table><blockquote><p><strong>Lot size note</strong>: if you don&#39;t know it, just ask: the assistant will pull <code>lotsize</code> from <code>get_option_symbol</code> first, then size the quantity correctly.</p></blockquote><p><strong>Prompts:</strong></p><ul><li><em>&quot;Buy 1 lot NIFTY ATM CE expiring 28NOV25&quot;</em></li><li><em>&quot;Short 2 lots BANKNIFTY OTM3 PE for next weekly expiry&quot;</em></li></ul><hr><h4 id="place-options-multi-order" tabindex="-1"><code>place_options_multi_order</code> <a class="header-anchor" href="#place-options-multi-order" aria-label="Permalink to &quot;`place_options_multi_order`&quot;">​</a></h4><p>Multi-leg option strategies (up to 20 legs). BUY legs are fired first for margin efficiency, then SELL legs. Supports per-leg overrides for <code>expiry_date</code>, <code>pricetype</code>, <code>price</code>, <code>product</code>, etc., perfect for calendar / diagonal spreads.</p><p><strong>Prompts:</strong></p><ul><li><em>&quot;Place an iron condor on NIFTY 28NOV25 at OTM5 and OTM10 strikes, 1 lot each, NRML&quot;</em></li><li><em>&quot;Build a long straddle on BANKNIFTY ATM for 25NOV25 expiry with limit orders at 250&quot;</em></li><li><em>&quot;Diagonal NIFTY spread: buy ITM2 CE 30DEC25, sell OTM2 CE 25NOV25, 1 lot&quot;</em></li></ul><hr><h4 id="modify-order" tabindex="-1"><code>modify_order</code> <a class="header-anchor" href="#modify-order" aria-label="Permalink to &quot;`modify_order`&quot;">​</a></h4><p>Change price / quantity / type / trigger on a working order.</p><table tabindex="0"><thead><tr><th>Param</th><th>Required</th><th>Notes</th></tr></thead><tbody><tr><td><code>order_id</code>, <code>symbol</code>, <code>action</code>, <code>exchange</code>, <code>product</code>, <code>quantity</code>, <code>price</code></td><td>Yes</td><td><code>price</code> is mandatory per the REST spec, use current price if unchanged</td></tr><tr><td><code>price_type</code>, <code>trigger_price</code>, <code>disclosed_quantity</code></td><td>No</td><td><code>price_type</code> defaults to <strong><code>LIMIT</code></strong>, unlike every other order tool, which defaults to <code>MARKET</code>. Modifying a working <code>SL-M</code> order without passing <code>price_type</code> converts it to <code>LIMIT</code>. <code>trigger_price</code> and <code>disclosed_quantity</code> default to 0</td></tr></tbody></table><p><strong>Prompts:</strong></p><ul><li><em>&quot;Modify order 250408001002736, change limit price to 16.5&quot;</em></li><li><em>&quot;Increase quantity of my open NIFTY CE buy order to 2 lots&quot;</em></li></ul><hr><h4 id="cancel-order" tabindex="-1"><code>cancel_order</code> <a class="header-anchor" href="#cancel-order" aria-label="Permalink to &quot;`cancel_order`&quot;">​</a></h4><p><strong>Prompt:</strong> <em>&quot;Cancel order 250408001002736&quot;</em></p><hr><h4 id="cancel-all-orders" tabindex="-1"><code>cancel_all_orders</code> <a class="header-anchor" href="#cancel-all-orders" aria-label="Permalink to &quot;`cancel_all_orders`&quot;">​</a></h4><p><strong>Prompts:</strong></p><ul><li><em>&quot;Cancel every pending order I have&quot;</em></li><li><em>&quot;Kill all open orders for strategy &#39;nifty scalper&#39;&quot;</em></li></ul><hr><h3 id="positions-holdings" tabindex="-1">Positions &amp; Holdings <a class="header-anchor" href="#positions-holdings" aria-label="Permalink to &quot;Positions &amp; Holdings&quot;">​</a></h3><h4 id="close-all-positions" tabindex="-1"><code>close_all_positions</code> <a class="header-anchor" href="#close-all-positions" aria-label="Permalink to &quot;`close_all_positions`&quot;">​</a></h4><p>Square off everything for a strategy.</p><p><strong>Prompt:</strong> <em>&quot;Close all my open positions now&quot;</em></p><hr><h4 id="get-open-position" tabindex="-1"><code>get_open_position</code> <a class="header-anchor" href="#get-open-position" aria-label="Permalink to &quot;`get_open_position`&quot;">​</a></h4><p>Query the current net quantity for a specific instrument.</p><p><strong>Prompts:</strong></p><ul><li><em>&quot;What&#39;s my current position in NHPC NSE MIS?&quot;</em></li><li><em>&quot;How many NIFTY futures am I long?&quot;</em></li></ul><hr><h4 id="get-position-book" tabindex="-1"><code>get_position_book</code> <a class="header-anchor" href="#get-position-book" aria-label="Permalink to &quot;`get_position_book`&quot;">​</a></h4><p>Every open position across instruments.</p><p><strong>Prompt:</strong> <em>&quot;Show me all open positions with unrealized P&amp;L&quot;</em></p><hr><h4 id="get-holdings" tabindex="-1"><code>get_holdings</code> <a class="header-anchor" href="#get-holdings" aria-label="Permalink to &quot;`get_holdings`&quot;">​</a></h4><p>Delivery/CNC holdings with today&#39;s P&amp;L, % move, and aggregate statistics.</p><p><strong>Prompts:</strong></p><ul><li><em>&quot;Show my demat holdings sorted by today&#39;s % change&quot;</em></li><li><em>&quot;What&#39;s the total unrealized P&amp;L on my long-term portfolio?&quot;</em></li></ul><hr><h4 id="get-funds" tabindex="-1"><code>get_funds</code> <a class="header-anchor" href="#get-funds" aria-label="Permalink to &quot;`get_funds`&quot;">​</a></h4><p>Cash, collateral, realized/unrealized M2M, utilized margin.</p><p><strong>Prompt:</strong> <em>&quot;How much free cash do I have for trading today?&quot;</em></p><hr><h3 id="order-tracking" tabindex="-1">Order Tracking <a class="header-anchor" href="#order-tracking" aria-label="Permalink to &quot;Order Tracking&quot;">​</a></h3><h4 id="get-order-status" tabindex="-1"><code>get_order_status</code> <a class="header-anchor" href="#get-order-status" aria-label="Permalink to &quot;`get_order_status`&quot;">​</a></h4><p><strong>Prompt:</strong> <em>&quot;Check status of order 250828000185002, did it fill?&quot;</em></p><hr><h4 id="get-order-book" tabindex="-1"><code>get_order_book</code> <a class="header-anchor" href="#get-order-book" aria-label="Permalink to &quot;`get_order_book`&quot;">​</a></h4><p>Every order today with statistics (open / complete / cancelled / rejected counts).</p><p><strong>Prompts:</strong></p><ul><li><em>&quot;Show today&#39;s order book&quot;</em></li><li><em>&quot;How many of my orders got rejected today and why?&quot;</em></li></ul><hr><h4 id="get-trade-book" tabindex="-1"><code>get_trade_book</code> <a class="header-anchor" href="#get-trade-book" aria-label="Permalink to &quot;`get_trade_book`&quot;">​</a></h4><p>Only executed fills.</p><p><strong>Prompt:</strong> <em>&quot;List all my executed trades today with average price&quot;</em></p><hr><h3 id="market-data" tabindex="-1">Market Data <a class="header-anchor" href="#market-data" aria-label="Permalink to &quot;Market Data&quot;">​</a></h3><h4 id="get-quote" tabindex="-1"><code>get_quote</code> <a class="header-anchor" href="#get-quote" aria-label="Permalink to &quot;`get_quote`&quot;">​</a></h4><p>LTP, bid, ask, OHLC, volume for one symbol.</p><p><strong>Prompts:</strong></p><ul><li><em>&quot;Get the latest quote for RELIANCE&quot;</em></li><li><em>&quot;What&#39;s NIFTY trading at right now?&quot;</em></li></ul><hr><h4 id="get-multi-quotes" tabindex="-1"><code>get_multi_quotes</code> <a class="header-anchor" href="#get-multi-quotes" aria-label="Permalink to &quot;`get_multi_quotes`&quot;">​</a></h4><p>Quotes for many symbols in one round-trip.</p><p><strong>Prompt:</strong> <em>&quot;Get quotes for RELIANCE, TCS, INFY, HDFCBANK and ICICIBANK&quot;</em></p><hr><h4 id="get-market-depth" tabindex="-1"><code>get_market_depth</code> <a class="header-anchor" href="#get-market-depth" aria-label="Permalink to &quot;`get_market_depth`&quot;">​</a></h4><p>Full 5-level bid/ask book plus total buy/sell qty and OI.</p><p><strong>Prompt:</strong> <em>&quot;Show the order book depth for SBIN&quot;</em></p><hr><h4 id="get-historical-data" tabindex="-1"><code>get_historical_data</code> <a class="header-anchor" href="#get-historical-data" aria-label="Permalink to &quot;`get_historical_data`&quot;">​</a></h4><p>OHLCV history. Two sources:</p><ul><li><code>source=&quot;api&quot;</code> (default) → live fetch from broker API</li><li><code>source=&quot;db&quot;</code> → local Historify DuckDB store (1m and D stored physically; other intervals, including custom ones like 2m/3m/W/M/Q/Y, computed on-the-fly via SQL)</li></ul><blockquote><p><strong><code>bars</code> defaults to 20.</strong> However wide a date range you ask for, the tool returns only the last 20 rows and sets <code>truncated: true</code>. Say how many bars you want (&quot;the last 200 daily bars&quot;) or the model will silently work from 20. The same default applies to <code>calculate_indicator</code>.</p></blockquote><p><strong>Prompts:</strong></p><ul><li><em>&quot;Get 5-minute SBIN candles from 1 Apr to 8 Apr 2025&quot;</em></li><li><em>&quot;Pull NIFTY daily data for the last 6 months from the local Historify DB&quot;</em></li><li><em>&quot;Give me weekly aggregates of BANKNIFTY for the past year using source=db&quot;</em></li></ul><hr><h4 id="get-option-chain" tabindex="-1"><code>get_option_chain</code> <a class="header-anchor" href="#get-option-chain" aria-label="Permalink to &quot;`get_option_chain`&quot;">​</a></h4><p>Real-time chain with CE/PE data per strike, LTP, bid/ask, OHLC, volume, OI, <code>lotsize</code>, moneyness labels. <code>strike_count=N</code> returns N strikes <strong>above and</strong> N below ATM, so roughly 2N+1 rows. Valid range is 1 to 100.</p><p><strong>Prompts:</strong></p><ul><li><em>&quot;Show me NIFTY option chain for 30DEC25, 10 strikes around ATM&quot;</em></li><li><em>&quot;Full BANKNIFTY option chain for this week&#39;s expiry&quot;</em></li></ul><hr><h3 id="instrument-search-symbols" tabindex="-1">Instrument Search &amp; Symbols <a class="header-anchor" href="#instrument-search-symbols" aria-label="Permalink to &quot;Instrument Search &amp; Symbols&quot;">​</a></h3><h4 id="search-instruments" tabindex="-1"><code>search_instruments</code> <a class="header-anchor" href="#search-instruments" aria-label="Permalink to &quot;`search_instruments`&quot;">​</a></h4><p>Fuzzy search across exchanges by name or symbol.</p><p><strong>Prompts:</strong></p><ul><li><em>&quot;Search for NIFTY 26000 Dec CE&quot;</em></li><li><em>&quot;Find all TATA stocks on NSE&quot;</em></li></ul><hr><h4 id="get-symbol-info" tabindex="-1"><code>get_symbol_info</code> <a class="header-anchor" href="#get-symbol-info" aria-label="Permalink to &quot;`get_symbol_info`&quot;">​</a></h4><p>Full metadata for one symbol: <code>brsymbol</code>, <code>lotsize</code>, <code>expiry</code>, <code>strike</code>, <code>tick_size</code>, <code>token</code>.</p><p><strong>Prompts:</strong></p><ul><li><em>&quot;Get symbol info for NIFTY30DEC25FUT on NFO&quot;</em></li><li><em>&quot;What&#39;s the lot size for BANKNIFTY futures?&quot;</em></li></ul><hr><h4 id="get-option-symbol" tabindex="-1"><code>get_option_symbol</code> <a class="header-anchor" href="#get-option-symbol" aria-label="Permalink to &quot;`get_option_symbol`&quot;">​</a></h4><p>Resolve ATM/ITM/OTM offset to the exact option symbol plus <code>lotsize</code>, <code>tick_size</code>, <code>underlying_ltp</code>. Expiry optional if the underlying includes one.</p><p><strong>Prompts:</strong></p><ul><li><em>&quot;Get the ATM CE symbol for NIFTY expiring 28OCT25&quot;</em></li><li><em>&quot;What&#39;s the OTM4 PE for BANKNIFTY next weekly?&quot;</em></li></ul><hr><h4 id="get-option-greeks" tabindex="-1"><code>get_option_greeks</code> <a class="header-anchor" href="#get-option-greeks" aria-label="Permalink to &quot;`get_option_greeks`&quot;">​</a></h4><p>Delta, Gamma, Theta, Vega, Rho + Implied Volatility using Black-76. Underlying is auto-detected, override with <code>underlying_symbol</code> / <code>underlying_exchange</code>, supply <code>forward_price</code> for custom / illiquid underlyings, and <code>expiry_time</code> for non-standard MCX contracts. <code>interest_rate</code> is the annualized risk-free rate in percent and <strong>defaults to 0</strong>, which materially shifts rho and theta: pass it when those matter.</p><p><strong>Prompts:</strong></p><ul><li><em>&quot;Calculate greeks for NIFTY25NOV2526000CE with 6.5% interest rate&quot;</em></li><li><em>&quot;What&#39;s the delta and IV of the ATM NIFTY CE for 28NOV25?&quot;</em></li></ul><hr><h4 id="get-synthetic-future" tabindex="-1"><code>get_synthetic_future</code> <a class="header-anchor" href="#get-synthetic-future" aria-label="Permalink to &quot;`get_synthetic_future`&quot;">​</a></h4><p>Put-call parity synthetic future price, useful for illiquid futures or weekly expiries that lack a traded future.</p><p><strong>Prompt:</strong> <em>&quot;What&#39;s the NIFTY synthetic future price for 25NOV25?&quot;</em></p><hr><h4 id="get-expiry-dates" tabindex="-1"><code>get_expiry_dates</code> <a class="header-anchor" href="#get-expiry-dates" aria-label="Permalink to &quot;`get_expiry_dates`&quot;">​</a></h4><p>All tradeable expiries for an underlying.</p><p><strong>Prompt:</strong> <em>&quot;List all NIFTY options expiries available on NFO&quot;</em></p><hr><h4 id="get-available-intervals" tabindex="-1"><code>get_available_intervals</code> <a class="header-anchor" href="#get-available-intervals" aria-label="Permalink to &quot;`get_available_intervals`&quot;">​</a></h4><p>Supported timeframes for <code>get_historical_data</code>.</p><p><strong>Prompt:</strong> <em>&quot;What intraday intervals are supported?&quot;</em></p><hr><h4 id="get-instruments" tabindex="-1"><code>get_instruments</code> <a class="header-anchor" href="#get-instruments" aria-label="Permalink to &quot;`get_instruments`&quot;">​</a></h4><p>Bulk instrument master download for an exchange (or all exchanges when <code>exchange</code> is omitted). Output is paginated, default limit 500, with a <code>truncated</code> flag.</p><p><strong>Prompts:</strong></p><ul><li><em>&quot;Download the NFO instrument master, first 500 rows&quot;</em></li><li><em>&quot;Get all MCX instruments available for trading&quot;</em></li></ul><hr><h4 id="get-index-symbols" tabindex="-1"><code>get_index_symbols</code> <a class="header-anchor" href="#get-index-symbols" aria-label="Permalink to &quot;`get_index_symbols`&quot;">​</a></h4><p>Returns the full standardized Tradeboard index symbol list (57 NSE + 40 BSE), rolled out uniformly across every supported broker.</p><p><strong>Prompts:</strong></p><ul><li><em>&quot;List all NSE index symbols I can subscribe to&quot;</em></li><li><em>&quot;Show me the BSE index list, I want to stream SENSEX50&quot;</em></li></ul><hr><h3 id="margin" tabindex="-1">Margin <a class="header-anchor" href="#margin" aria-label="Permalink to &quot;Margin&quot;">​</a></h3><h4 id="calculate-margin" tabindex="-1"><code>calculate_margin</code> <a class="header-anchor" href="#calculate-margin" aria-label="Permalink to &quot;`calculate_margin`&quot;">​</a></h4><p>SPAN + exposure margin for a hypothetical position set. Accepts an array of legs with <code>symbol</code>, <code>exchange</code>, <code>action</code>, <code>product</code>, <code>pricetype</code>, <code>quantity</code>.</p><p><strong>Prompts:</strong></p><ul><li><em>&quot;Calculate margin for 1 lot NIFTY 25000 CE buy + 1 lot 25500 CE sell, 25NOV25 expiry&quot;</em></li><li><em>&quot;How much margin do I need for a BANKNIFTY short straddle at ATM for next week?&quot;</em></li></ul><hr><h3 id="analyzer" tabindex="-1">Analyzer <a class="header-anchor" href="#analyzer" aria-label="Permalink to &quot;Analyzer&quot;">​</a></h3><h4 id="analyzer-status" tabindex="-1"><code>analyzer_status</code> <a class="header-anchor" href="#analyzer-status" aria-label="Permalink to &quot;`analyzer_status`&quot;">​</a></h4><p>Am I in simulated (analyzer) or live mode?</p><p><strong>Prompt:</strong> <em>&quot;Am I in live or analyzer mode right now?&quot;</em></p><hr><h4 id="analyzer-toggle" tabindex="-1"><code>analyzer_toggle</code> <a class="header-anchor" href="#analyzer-toggle" aria-label="Permalink to &quot;`analyzer_toggle`&quot;">​</a></h4><p>Flip between simulated and live trading. Analyzer mode returns sandbox order IDs in the same <code>YYMMDD</code> + sequence shape as a real one, and the response carries <code>mode: &quot;analyze&quot;</code>, without touching the broker. Read the <code>mode</code> field, not the order ID, to tell simulated from live.</p><p><strong>Prompts:</strong></p><ul><li><em>&quot;Switch to analyzer mode before I test this strategy&quot;</em></li><li><em>&quot;Turn off analyzer, I want to go live&quot;</em></li></ul><hr><h3 id="market-calendar" tabindex="-1">Market Calendar <a class="header-anchor" href="#market-calendar" aria-label="Permalink to &quot;Market Calendar&quot;">​</a></h3><h4 id="get-holidays" tabindex="-1"><code>get_holidays</code> <a class="header-anchor" href="#get-holidays" aria-label="Permalink to &quot;`get_holidays`&quot;">​</a></h4><p>Full holiday list for a year (year optional → defaults to current year).</p><p><strong>Prompts:</strong></p><ul><li><em>&quot;What are the trading holidays in 2026?&quot;</em></li><li><em>&quot;List this year&#39;s market holidays&quot;</em></li></ul><hr><h4 id="get-timings" tabindex="-1"><code>get_timings</code> <a class="header-anchor" href="#get-timings" aria-label="Permalink to &quot;`get_timings`&quot;">​</a></h4><p>Exchange open/close epoch timestamps for a given date (date optional → defaults to today).</p><p><strong>Prompt:</strong> <em>&quot;What are today&#39;s market timings across NSE, BFO and MCX?&quot;</em></p><hr><h4 id="check-holiday" tabindex="-1"><code>check_holiday</code> <a class="header-anchor" href="#check-holiday" aria-label="Permalink to &quot;`check_holiday`&quot;">​</a></h4><p>This tool is registered and appears in MCP clients, but it is currently <strong>unavailable</strong>: it calls <code>/api/v1/checkholiday</code>, which is not a registered Tradeboard REST endpoint. Calls return an endpoint error instead of a holiday result. Use <code>get_timings</code> for one date or <code>get_holidays</code> for the yearly list.</p><hr><h3 id="utilities" tabindex="-1">Utilities <a class="header-anchor" href="#utilities" aria-label="Permalink to &quot;Utilities&quot;">​</a></h3><h4 id="get-tradeboard-version" tabindex="-1"><code>get_tradeboard_version</code> <a class="header-anchor" href="#get-tradeboard-version" aria-label="Permalink to &quot;`get_tradeboard_version`&quot;">​</a></h4><p><strong>Prompt:</strong> <em>&quot;What version of the tradeboard library is running?&quot;</em></p><hr><h4 id="validate-order-constants" tabindex="-1"><code>validate_order_constants</code> <a class="header-anchor" href="#validate-order-constants" aria-label="Permalink to &quot;`validate_order_constants`&quot;">​</a></h4><p>Quick cheat-sheet of valid exchanges, product types, price types, actions, and intervals, useful when the model wants to double-check a parameter before sending an order.</p><p><strong>Prompt:</strong> <em>&quot;Remind me of the valid product types and price types&quot;</em></p><hr><h4 id="send-telegram-alert" tabindex="-1"><code>send_telegram_alert</code> <a class="header-anchor" href="#send-telegram-alert" aria-label="Permalink to &quot;`send_telegram_alert`&quot;">​</a></h4><p>Push a Telegram notification via the Tradeboard Telegram bot (must be configured in Tradeboard settings first).</p><table tabindex="0"><thead><tr><th>Param</th><th>Required</th><th>Notes</th></tr></thead><tbody><tr><td><code>username</code></td><td>Yes</td><td>Your Tradeboard login ID. There is no default, so name it in the prompt</td></tr><tr><td><code>message</code></td><td>Yes</td><td>Body text</td></tr><tr><td><code>priority</code></td><td>No</td><td>1 to 10, defaults to 5</td></tr></tbody></table><p>This is the one tool annotated as a write that is gated on <code>read:account</code>, so a read-only remote session can still send Telegram messages.</p><p><strong>Prompts:</strong></p><ul><li><em>&quot;Send me a Telegram alert: NIFTY crossed 26000, priority 8&quot;</em></li><li><em>&quot;Ping me on Telegram if my NIFTY CE fills&quot;</em></li></ul><hr><h3 id="technical-research" tabindex="-1">Technical Research <a class="header-anchor" href="#technical-research" aria-label="Permalink to &quot;Technical Research&quot;">​</a></h3><p>Research tools fetch broker or Historify history and calculate compact results on the Tradeboard server. Common optional controls are <code>interval</code>, <code>start_date</code>, <code>end_date</code>, <code>lookback_bars</code>, <code>lookback_days</code>, and <code>source</code> (<code>api</code> or <code>db</code>). <code>multi_timeframe_analysis</code> is the exception: it takes a list called <code>intervals</code>, not a single <code>interval</code>.</p><h4 id="calculate-indicator" tabindex="-1"><code>calculate_indicator</code> <a class="header-anchor" href="#calculate-indicator" aria-label="Permalink to &quot;`calculate_indicator`&quot;">​</a></h4><p>Run an <code>tradeboard.ta</code> indicator by name. Supply <code>symbol</code>, <code>exchange</code>, and <code>indicator</code>; use <code>params</code> for indicator arguments, <code>inputs</code> when automatic OHLCV input detection is insufficient, and <code>bars</code> to limit returned rows.</p><p><strong>Prompt:</strong> <em>&quot;Calculate RSI(14) and the latest 20 values for RELIANCE daily candles&quot;</em></p><h4 id="get-trend-snapshot" tabindex="-1"><code>get_trend_snapshot</code> <a class="header-anchor" href="#get-trend-snapshot" aria-label="Permalink to &quot;`get_trend_snapshot`&quot;">​</a></h4><p>Return a one-call trend bundle containing SMA, EMA, Supertrend, ADX/DMI, and Ichimoku values.</p><p><strong>Prompt:</strong> <em>&quot;Give me a daily trend snapshot for NIFTY&quot;</em></p><h4 id="get-momentum-snapshot" tabindex="-1"><code>get_momentum_snapshot</code> <a class="header-anchor" href="#get-momentum-snapshot" aria-label="Permalink to &quot;`get_momentum_snapshot`&quot;">​</a></h4><p>Return RSI, MACD, Stochastic, CCI, and Williams %R values for one symbol and interval.</p><p><strong>Prompt:</strong> <em>&quot;Show a 15-minute momentum snapshot for SBIN&quot;</em></p><h4 id="get-volatility-snapshot" tabindex="-1"><code>get_volatility_snapshot</code> <a class="header-anchor" href="#get-volatility-snapshot" aria-label="Permalink to &quot;`get_volatility_snapshot`&quot;">​</a></h4><p>Return ATR, NATR, Bollinger, Keltner, Donchian, and historical-volatility values.</p><p><strong>Prompt:</strong> <em>&quot;Compare the current volatility measures for INFY on daily candles&quot;</em></p><h4 id="get-support-resistance" tabindex="-1"><code>get_support_resistance</code> <a class="header-anchor" href="#get-support-resistance" aria-label="Permalink to &quot;`get_support_resistance`&quot;">​</a></h4><p>Calculate pivot points, Donchian levels, and rolling highest-high and lowest-low values. <code>period</code> defaults to 20.</p><p><strong>Prompt:</strong> <em>&quot;Find 20-day support and resistance levels for RELIANCE&quot;</em></p><h4 id="detect-signals" tabindex="-1"><code>detect_signals</code> <a class="header-anchor" href="#detect-signals" aria-label="Permalink to &quot;`detect_signals`&quot;">​</a></h4><p>Find recent bullish and bearish events. <code>signal_type</code> selects the rule and defaults to <code>ema_cross</code>; valid values are <code>ema_cross</code>, <code>sma_cross</code>, <code>macd_cross</code>, <code>supertrend_flip</code>, and <code>rsi_threshold</code>. <code>fast</code> (20) and <code>slow</code> (50) set the crossover lengths, <code>period</code> (14) the RSI length, <code>upper</code> (70) and <code>lower</code> (30) the RSI thresholds, and <code>limit</code> (20) bounds the returned events.</p><p><strong>Prompt:</strong> <em>&quot;Find the latest EMA 20/50 cross signals for TCS&quot;</em></p><h4 id="screen-instruments" tabindex="-1"><code>screen_instruments</code> <a class="header-anchor" href="#screen-instruments" aria-label="Permalink to &quot;`screen_instruments`&quot;">​</a></h4><p>Evaluate a modest list of <code>{symbol, exchange}</code> pairs. <code>condition</code> defaults to <code>rsi_below</code>; valid values are <code>rsi_below</code>, <code>rsi_above</code>, <code>price_above_sma</code>, <code>price_below_sma</code>, <code>supertrend_bullish</code>, and <code>supertrend_bearish</code>. <code>value</code> (30.0) is the threshold and <code>period</code> (14) the indicator length. History is fetched per symbol, so keep broker-backed lists small.</p><p><strong>Prompt:</strong> <em>&quot;Screen RELIANCE, INFY, TCS, and SBIN for RSI below 35&quot;</em></p><h4 id="multi-timeframe-analysis" tabindex="-1"><code>multi_timeframe_analysis</code> <a class="header-anchor" href="#multi-timeframe-analysis" aria-label="Permalink to &quot;`multi_timeframe_analysis`&quot;">​</a></h4><p>Compute one indicator across several timeframes. The default timeframes are <code>5m</code>, <code>15m</code>, <code>1h</code>, and <code>D</code>.</p><p><strong>Prompt:</strong> <em>&quot;Check RSI confluence for NIFTY across 5m, 15m, 1h, and daily&quot;</em></p><h4 id="correlation-beta" tabindex="-1"><code>correlation_beta</code> <a class="header-anchor" href="#correlation-beta" aria-label="Permalink to &quot;`correlation_beta`&quot;">​</a></h4><p>Align two symbols on common timestamps and return rolling correlation, rolling beta, linear-regression slope, and full-sample Pearson correlation.</p><p><strong>Prompt:</strong> <em>&quot;Calculate 60-day correlation and beta for RELIANCE versus NIFTY&quot;</em></p><hr><h3 id="worked-multi-tool-workflows" tabindex="-1">Worked Multi-Tool Workflows <a class="header-anchor" href="#worked-multi-tool-workflows" aria-label="Permalink to &quot;Worked Multi-Tool Workflows&quot;">​</a></h3><p>Real strength shows when the assistant chains tools on its own. Example prompts:</p><p><strong>1. End-to-end iron condor (analyzer mode):</strong></p><blockquote><p><em>&quot;Set up a NIFTY iron condor for next week&#39;s expiry. Find the expiry, pull the option chain, use OTM5 strikes on both sides, calculate the margin required, and, only if margin is under ₹1L, place it in analyzer mode using 1 lot per leg.&quot;</em></p></blockquote><p>The assistant will chain: <code>get_expiry_dates</code> → <code>get_option_chain</code> → <code>get_option_symbol</code> (for lot size) → <code>calculate_margin</code> → <code>analyzer_status</code> / <code>analyzer_toggle</code> → <code>place_options_multi_order</code>.</p><p><strong>2. Pre-market checklist:</strong></p><blockquote><p><em>&quot;Before I start trading: is the market open today on NSE and MCX, what&#39;s my free cash, what&#39;s my current position book, and what&#39;s NIFTY spot right now?&quot;</em></p></blockquote><p>Chains: <code>get_timings</code> → <code>get_funds</code> → <code>get_position_book</code> → <code>get_quote</code>.</p><p><strong>3. Options greeks scan:</strong></p><blockquote><p><em>&quot;Pull the NIFTY option chain for 25NOV25 within 5 strikes of ATM, then compute greeks for the ATM CE and PE with 6.5% interest rate, tell me which has higher vega.&quot;</em></p></blockquote><p>Chains: <code>get_option_chain</code> → <code>get_option_symbol</code> (ATM) × 2 → <code>get_option_greeks</code> × 2.</p><p><strong>4. Square-off with Telegram confirmation:</strong></p><blockquote><p><em>&quot;Square off everything, cancel all pending orders, then send me a Telegram alert summarizing what got closed with the realized P&amp;L.&quot;</em></p></blockquote><p>Chains: <code>cancel_all_orders</code> → <code>close_all_positions</code> → <code>get_trade_book</code> → <code>send_telegram_alert</code>.</p><hr><h3 id="quick-prompt-patterns" tabindex="-1">Quick Prompt Patterns <a class="header-anchor" href="#quick-prompt-patterns" aria-label="Permalink to &quot;Quick Prompt Patterns&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Intent</th><th>Prompt pattern</th></tr></thead><tbody><tr><td>Status check</td><td><em>&quot;What&#39;s my {thing}?&quot;</em></td></tr><tr><td>Single action</td><td><em>&quot;{Buy/Sell} {qty} {symbol} at {price}&quot;</em></td></tr><tr><td>Multi-leg</td><td><em>&quot;Build a {strategy} on {underlying} {expiry} with {offsets}&quot;</em></td></tr><tr><td>Safety-first</td><td><em>&quot;In analyzer mode, {do the thing}&quot;</em></td></tr><tr><td>Conditional</td><td><em>&quot;Only if {condition}, then {action}&quot;</em></td></tr><tr><td>Research</td><td><em>&quot;Show me {chain/greeks/history} and recommend {levels}&quot;</em></td></tr></tbody></table><hr><h3 id="safety-tips" tabindex="-1">Safety Tips <a class="header-anchor" href="#safety-tips" aria-label="Permalink to &quot;Safety Tips&quot;">​</a></h3><ul><li>Start in <strong>analyzer mode</strong> (<code>analyzer_toggle True</code>) while you get comfortable. Orders look real but never leave Tradeboard.</li><li>Use phrases like <em>&quot;only if margin is under X&quot;</em> or <em>&quot;ask me to confirm before placing&quot;</em> and the assistant will pause for your OK.</li><li>Use a unique <code>strategy</code> name per use-case (e.g., <em>&quot;use strategy &#39;nifty scalper&#39;&quot;</em>) so MCP-driven activity is cleanly separable from manual orders in logs.</li><li>For live trading, set up the Tradeboard Telegram bot and ask the assistant to <em>&quot;send a Telegram alert after every order fill&quot;</em>. You get a realtime feed without staring at the screen.</li></ul><hr><h3 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h3><ul><li>MCP Server Setup Guide: install, configure Claude / Cursor / Windsurf, broker prerequisites</li><li>Tradeboard Symbol Format: how equity / future / option symbols are constructed</li><li>API Documentation: underlying REST endpoints each MCP tool wraps</li></ul>',259)])])}const m=o(d,[["render",i]]);export{p as __pageData,m as default};
